using UnscRelay.Core;
internal static class LocalApplicationLeaseChecks
{
 public static int Run(){var root=Directory.CreateTempSubdirectory("relay-host-lease-");var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS local application lease: "+label);}try{using(var first=new LocalApplicationLease(root.FullName)){try{using var second=new LocalApplicationLease(root.FullName);throw new Exception("Concurrent host acquired data root");}catch(IOException){Check(true,"a second host cannot load or mutate the same data root");}}using(var restarted=new LocalApplicationLease(root.FullName)){Check(true,"restart acquires the data root after the previous host releases it");}File.Delete(Path.Combine(root.FullName,"relay-session.lock"));var target=Path.Combine(root.FullName,"outside.txt");File.WriteAllText(target,"sentinel");File.CreateSymbolicLink(Path.Combine(root.FullName,"relay-session.lock"),target);try{using var linked=new LocalApplicationLease(root.FullName);throw new Exception("Linked lease file accepted");}catch(IOException){Check(File.ReadAllText(target)=="sentinel","a linked lease file fails closed without touching its target");}Console.WriteLine("Local application lease checks: "+count);return 0;}finally{root.Delete(true);}}
}
